解法一：合并到新数组
```c
double findMedianSortedArrays(int* nums1, int nums1Size, int* nums2, int nums2Size){
    int total = nums1Size + nums2Size;
    int *merged = malloc(total * sizeof(int));
    int i=0,j=0,k=0;
    while(i<nums1Size && j<nums2Size) merged[k++] = nums1[i] <= nums2[j] ? nums1[i++] : nums2[j++];
    while(i<nums1Size) merged[k++] = nums1[i++];
    while(j<nums2Size) merged[k++] = nums2[j++];
    double ans = (total & 1) ? merged[total/2] : (merged[total/2 - 1] + merged[total/2]) / 2.0;
    free(merged);
    return ans;
}
```

解法二：双指针原地找第 k 小（不开数组）
```c
double findMedianSortedArrays(int* nums1, int nums1Size, int* nums2, int nums2Size){
    int total = nums1Size + nums2Size;
    int midR = total / 2;          // 要找的下标（0-based）
    int midL = (total - 1) / 2;    // 偶数时左边那个下标；奇数时等于 midR
    int i = 0, j = 0, cnt = 0;
    int leftVal = 0, rightVal = 0;
    // 逐个比赛，谁小谁出来
    while (cnt <= midR) {
        int cur;
        if (i < nums1Size && (j >= nums2Size || nums1[i] <= nums2[j])) cur = nums1[i++];
        else cur = nums2[j++];
        if (cnt == midL) leftVal = cur;
        if (cnt == midR) rightVal = cur;
        cnt++;
    }
    return (leftVal + rightVal) / 2.0;
}
```
Careful: midL = (total-1)/2: for total=4 → 1; midR = 2 → (merged[1]+merged[2])/2 correct. For total=1 → midL=0, midR=0 → cur/1.0? (leftVal+rightVal)/2.0 = 2*val/2 = val correct. For total=3: midL=1, midR=1 → merged[1] correct. Total=2: midL=0, midR=1 → correct. Good.

Note: `(leftVal + rightVal) / 2.0` — ints up to 1e6, sum up to 2e6 fits in int. Fine.

解法三：二分划分 O(log(min(m,n)))
Standard: always binary search on the shorter array. Use nums1 as shorter by swapping.

```c
double findMedianSortedArrays(int* nums1, int nums1Size, int* nums2, int nums2Size){
    // 保证 nums1 是短的那个：二分用在短数组上，复杂度才是 log(min(m,n))
    if (nums1Size > nums2Size) return findMedianSortedArrays(nums2, nums2Size, nums1, nums1Size);
    int m = nums1Size, n = nums2Size;
    int total = m + n;
    int half = (total + 1) / 2;   // 左半边要放的个数（+1 是为奇数时左边多一个）
    int lo = 0, hi = m;           // i 的搜索范围：从 nums1 里取几个放左边
    while (lo <= hi) {
        int i = (lo + hi) / 2;    // nums1 左半取 i 个
        int j = half - i;         // nums2 左半取 j 个
        // 四个边界值：越界就用 ±无穷 代替，省掉一堆 if
        int inLeft  = (i > 0) ? nums1[i - 1] : INT_MIN;
        int inRight = (i < m) ? nums1[i]     : INT_MAX;
        int jnLeft  = (j > 0) ? nums2[j - 1] : INT_MIN;
        int jnRight = (j < n) ? nums2[j]     : INT_MAX;

        if (inLeft <= jnRight && jnLeft <= inRight) {
            // 划分正确了
            if (total & 1) return inLeft > jnLeft ? inLeft : jnLeft;  // 奇数：左边最大就是中位数
            int leftMax  = inLeft > jnLeft ? inLeft : jnLeft;
            int rightMin = inRight < jnRight ? inRight : jnRight;
            return (leftMax + rightMin) / 2.0;
        } else if (inLeft > jnRight) {
            hi = i - 1;   // nums1 左边取多了，往左收
        } else {
            lo = i + 1;   // nums1 左边取少了，往右扩
        }
    }
    return 0.0; // 走不到这儿
