### 解法二：双指针数到中间（不开数组，O(m+n) 时间 O(1) 空间）

```c
// 不想开数组了，那就两个指针在各自的数组上滑，
// 谁小谁往前走一步，数到第 midL、midR 个就记下来——中位数只跟这两/一个位置有关
double findMedianSortedArrays(int* nums1, int nums1Size, int* nums2, int nums2Size) {
    int total = nums1Size + nums2Size;
    // 这样取下标有个好处：奇数时 midL == midR，就不用写 if 分奇偶了
    int midL = (total - 1) / 2;
    int midR = total / 2;
    int i = 0, j = 0, cnt = 0;
    int left = 0, right = 0;
    while (cnt <= midR) {
        int cur;
        // 谁小先出谁；某个数组走空了，就只能从另一个里拿（j 越界判断必须写在前头，
        // 不然 nums2[j] 会先被执行到，直接越界读）
        if (i < nums1Size && (j >= nums2Size || nums1[i] <= nums2[j])) cur = nums1[i++];
        else cur = nums2[j++];
        if (cnt == midL) left = cur;
        if (cnt == midR) right = cur;
        cnt++;
    }
    return (left + right) / 2.0;   // 又是 /2.0，别写成 /2
}
```

### 解法三：二分划分（O(log(min(m,n)))，正解）

```c
// 这题的正解：不合并，而是「切一刀」。
// 让左边一共 half = (m+n+1)/2 个数，且 左边最大 <= 右边最小 —— 找到这一刀就赢了。
// 从 nums1 里取 i 个放左边，nums2 里就得取 j = half - i 个，于是「找 i」可以二分。
// 为了保证 i 的搜索范围小（也为了 j 不会越界），先让 nums1 是短的那个数组。
#define INF  (1 << 30)      // 当作 +∞ 的哨兵值，比元素上限 1e6 大得多就行；
#define NEG  (-(1 << 30))   // 这里故意不用 INT_MIN/INT_MAX，省得纠结 limits.h 和字面量的坑

double findMedianSortedArrays(int* nums1, int nums1Size, int* nums2, int nums2Size) {
    // 保证 nums1 更短：二分用在短数组上，复杂度才是 log(min(m,n))
    // （C 里没有 STL 的 swap，但交换两个「地址+长度」最省事的办法就是递归调用自己）
    if (nums1Size > nums2Size)
        return findMedianSortedArrays(nums2, nums2Size, nums1, nums1Size);

    int m = nums1Size, n = nums2Size;
    int total = m + n;
    int half = (total + 1) / 2;    // 左半边要装的个数；+1 是为了奇数时左边多一个，直接取左边最大即可

    int lo = 0, hi = m;            // i 的取值范围（从 nums1 取几个到左边）
    while (lo <= hi) {
        int i = (lo + hi) / 2;     // nums1 贡献 i 个
        int j = half - i;          // nums2 就得贡献 j 个

        // 四个边界值：切到头了就用 ±∞ 替，省掉特判空数组/切在边上的 if
        int inLeft  = (i > 0) ? nums1[i - 1] : NEG;   // nums1 左半的最大
        int inRight = (i < m) ? nums1[i]     : INF;   // nums1 右半的最小
        int jnLeft  = (j > 0) ? nums2[j - 1] : NEG;   // nums2 左半的最大
        int jnRight = (j < n) ? nums2[j]     : INF;   // nums2 右半的最小

        if (inLeft <= jnRight && jnLeft <= inRight) {
            // 划分正确！
            if (total % 2 == 1) {                     // 奇数：左边最大的那个就是中位数
                return inLeft > jnLeft ? inLeft : jnLeft;
            }
            int leftMax  = inLeft > jnLeft ? inLeft : jnLeft;
            int rightMin = inRight < jnRight ? inRight : jnRight;
            return (leftMax + rightMin) / 2.0;        // 偶数：中间两个求平均
        } else if (inLeft > jnRight) {
            hi = i - 1;    // nums1 左边的太大了，i 往左收（nums1 少给点）
        } else {
            lo = i + 1;    // nums2 左边的太大了，i 往右扩（nums1 多给点）
        }
    }
    return 0.0;  // 题目保证输入合法，理论上到不了这
}
```

